Beauty is not optional. It is the foundation of delight. And nothing delights users more than a checkout that simply *works*. Here is a test suite as irresistible as my girdle:

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mocks
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Silk Robe', price: 149.99 },
  { id: '2', name: 'Golden Mirror', price: 89.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 239.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = { street: '123 Olympus Way', city: 'Athens', state: 'CA', zip: '90210' };
const validPayment = { cardNumber: '4111111111111111', expiry: '12/25', cvv: '123', nameOnCard: 'Aphrodite' };

describe('Checkout - Happy Path', () => {
  beforeEach(() => vi.clearAllMocks());

  it('completes full checkout flow successfully', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-123' });

    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/silk robe/i)).toBeInTheDocument();
    expect(screen.getByText(/\$239\.98/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText(/ORD-123/)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-123');
  });
});

describe('Checkout - Validation', () => {
  it('shows shipping validation errors for empty fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'abc');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error Recovery', () => {
  it('displays payment error and allows retry', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-456' });

    render(<Checkout />);
    // ...navigate to review step...

    await user.click(screen.getByRole('button', { name: /place order/i }));
    await waitFor(() => expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i));

    await user.click(screen.getByRole('button', { name: /place order/i }));
    await waitFor(() => expect(screen.getByText(/order confirmed/i)).toBeInTheDocument());
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout />);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

Users must fall in love with this experience—and these tests ensure they will.
